UNIT_OF_DT_DEFINITION_THROUGHPUT = 'k'
MAX_IPERF_INTERVALS_DELAY = 30
DT_MAX_TIME = 86400
CONTROL_APP_LABEL = "control_app"


class AndroidDataTransfer(IperfPluginDataTransfer):  # pylint: disable=unnecessary-pass
    """Object responsible for managing Android data transfer."""

    # pylint: disable=protected-access, too-many-instance-attributes
    def __init__(self, name, dt_definition, configuration, ue_instance, logger_name='ute_ue'):
        """
        Object responsible for managing iperf data transfer for AndroidUe
        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param ue_instance:
        """
        super().__init__(name, dt_definition, configuration, logger_name)
        self.logger.debug(f"{self.name}: creating instance of AndroidDataTransfer")

        self.success_started = False
        self.reports_received = False
        self.avg_throughput = None
        self.datagram_loss = None
        self._port = None
        self.client_start_time = None
        self.client_finish_time = None
        self.iperf_output = defaultdict(list)
        self.last_read_time = {}
        self.iperf_cmds = {}
        self.additional_options = {}
        self.ue_instance = ue_instance
        self.stopping_gate = ActionGate()
        self._ensure_bandwidth_is_set_for_udp()
        self.dt_config = AndroidUeDtConfigPacker(self._dt_definition, self._configuration, self.logger).get_config()
        self.iperf_report_parser = IperfServerReportParser()
        self.burst = BurstMode(dt_config=self.dt_config, iperf_report_parser=self.iperf_report_parser,
                               logger=self.logger)
        self.logger.debug(f"{self.name} configuration: {self.dt_config}")
        self.ssh_manager = self._create_ssh_manager_and_register_host(self.dt_config['app_server'])

        self.ue_endpoint = UeIperfEndpoint(self.ue_instance.rpc_client, self.name, self.dt_config, self.ue_instance.id)
        self.app_server_endpoint = AppServerIperfEndpoint(self.ssh_manager, self.name, self.dt_config)

        self._set_allowed_iperf_delays()

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self.logger.debug(f"{self.name}: starting data transfer")
        self.last_read_time = {}
        self._port = None
        self.stopping_gate.open_action_gate()
        # getting timeout from config
        dt_startup_timeout = int(self._dt_definition.protocol_details.get('timeout', 0))
        # start iperf server with full timeout and record server startup time
        server_startup_time = time.time()
        if self.kill_previous:
            port = self.dt_config['robot_kwargs'].get("port")
            if not port:
                raise KillIperfByPortMissingPort("Passed `kill_previous` without given port")
            self.logger.debug(f"Killing iperf running on port={port}")
            if self.dt_config['direction'] == 'dl':
                self.ue_endpoint.kill_iperf_by_port(port)
                self._kill_appserver_iperf_by_port(port)
            else:
                self._kill_appserver_iperf_by_port(port)
                self.ue_endpoint.kill_iperf_by_port(port)
        try:
            self._start_iperf_and_wait_for_startup(endpoint=self.server, timeout=dt_startup_timeout)
            server_startup_time = time.time() - server_startup_time
            # start iperf client with timeout - server starting time = timeout left to start client
            self._start_iperf_and_wait_for_startup(endpoint=self.client,
                                                   timeout=int(dt_startup_timeout - server_startup_time))
        except IperfStuckException as e:
            # Make sure that iperf is stopped on both endpoints for future runs
            self.server.kill_iperf()
            self.client.kill_iperf()
            self.logger.debug(f"Trying to release aliases after failed start of {self.name} data transfer")
            release_aliases([self.name])
            raise e
        super().start()
        self.client_start_time = time.time()
        self.client_finish_time = None
        self.success_started = True
        self.is_dt_running = True
        self.logger.info(f"{self.name}: successfully started")

    def _kill_appserver_iperf_by_port(self, port):
        app_server_ssh_manager = self._create_ssh_manager_and_register_host(self.dt_config['app_server'])
        ip = self.dt_config['app_server']['address']
        self.logger.debug(f'Killing iperf by port on App Server: ip={ip}, port={port}')
        pid_cmd = f'ps -ef|grep iperf|grep -v "grep"|grep {port}' + "|awk '{print $2}'| xargs kill -9"
        app_server_ssh_manager.run_cmd_and_get_output_lines(cmd=pid_cmd, hostname=ip)
        app_server_ssh_manager.close_all_ssh_connections()

    def stop(self, should_raise=True):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :param should_raise: Allow to raise an exception or rather to log warning
        :return: None
        """
        self.logger.debug(f'{self.name}: stopping data transfer')
        super().stop()
        try:
            if self.stopping_gate.is_action_required():
                # 1) iperf status validation
                msg_error = ""
                try:
                    self._read_iperf_output_and_validate_status()
                except Exception as exc:
                    msg_error = f"Validating iperf status on stop failed:\n{exc}"
                # 2) iperf stop
                self.logger.debug(f"{self.name}: stopping iperf server on {repr(self.server)}")
                self._stop_endpoint(endpoint=self.server)
                if self.client.is_iperf_running():
                    self.logger.debug(f"{self.name}: stopping iperf client on {repr(self.client)}")
                    self._stop_endpoint(endpoint=self.client)
                    self.client_finish_time = time.time()
                self.logger.debug(f"{self.name}: data transfer successfully stopped")
                # 3) iperf status validation report to robot
                if msg_error and should_raise:
                    raise Exception(repr(msg_error))
                elif msg_error:
                    robot_logger.warn(msg_error)
                    self.logger.debug(f"Releasing iperf {self.name} resource meets fail {msg_error}")
            else:
                self.logger.debug(f'{self.name}: was already stopped earlier')
        finally:
            self._log_iperf_reports()
            self.is_dt_running = False

    def _stop_endpoint(self, endpoint):
        """
        Stops iperf server gracefully with timeout.
        :param endpoint: iperf server or client
        :return: None
        """
        retries = 2
        for _ in range(retries):
            # Attempt to stop iperf on endpoint
            self._run_action_without_raising(endpoint.kill_iperf)
            if self.port and isinstance(endpoint, UeIperfEndpoint):
                self.logger.debug(f"{self.name}: Try stopping iperf on on specific port={self.port}")
                self._run_action_without_raising(endpoint.kill_iperf_by_port, self.port)

            # Check if succeeded and if so finish
            if not endpoint.is_iperf_running():
                self.logger.debug(f"{self.name}: data transfer endpoint {endpoint} stopped successfully")
                return
        self.logger.warning(f"{self.name}: data transfer endpoint {endpoint} did not stopped!")

    def await_finish(self):
        """
        Waits until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        if self.get_definition().is_forever_duration() or self.dt_config['duration'] == DT_MAX_TIME:
            raise DataTransferException("Can not await forever."
                                        f"\nPlease set finite duration for {self.name} data transfer")
        try:
            iperf_interval = int(self.dt_config['interval'])
            while True:
                if not self.is_running():
                    break
                time.sleep(iperf_interval)
        finally:
            self.stop()
        self.logger.info(f"{self.name}: data transfer finished. Releasing await.")

    def is_running(self):
        """
        Checks if both client and server are running:
        App Server: checks if paramiko connection has command exit status
        UE: checks if data transfer on UEPC is in active state
        Check is skipped if data transfer earlier was stopped, False is returned immediately
        :return: boolean
        """
        if self.is_dt_running:
            self._read_iperf_output_and_validate_status()
            client_iperf_running = self.client.is_iperf_running()
            if not client_iperf_running:
                self.client_finish_time = time.time()
                self.logger.debug(f"{self.name}: iperf client is not running, "
                                  f"recording data transfer finish time: {self.client_finish_time}")
            self.is_dt_running = self.server.is_iperf_running() and client_iperf_running
        return self.is_dt_running

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""
        try:
            self.logger.debug(f'{self.name}: checking if data transfer is alive')
            iperf_interval = int(self.dt_config['interval'])
            max_time_without_output = iperf_interval * MAX_IPERF_INTERVALS_DELAY / 2

            if not self.is_running():
                self.logger.debug(f'{self.name}: skipping check. Data transfer is already finished.')
                return

            validation_start_time = time.time()
            while time.time() < validation_start_time + max_time_without_output:
                time.sleep(iperf_interval)
                self._read_iperf_output_and_validate_status()
                # Checking only server side
                # if iperf server receives the packets from client, then the client is active too
                if not self.last_read_time[self.server]:
                    self.logger.debug(f"{self.name}: No server out yet. Unable to check data transfer")
                    continue

                if self.last_read_time[self.server] > validation_start_time:
                    self.logger.debug(f"{self.name}: data transfer is alive")
                    return

            raise IperfStuckException(f"{self.name}: server didn't receive any data in {max_time_without_output}s.\n"
                                      "Please check your network connectivity between client and server.\n"
                                      "Make sure UE didn't change IP address during data transfer.\n")
        finally:
            self._log_iperf_reports(tail=60)

    def get_average_throughput(self, omit=0, end=0, tput_collection_src=None, format=None):  # Noqa: C901
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or
        from 'dt.start()' to 'dt.stop()' if data transfer is already finished or
        with currently available iperf intervals that were already transferred.

        :param omit: it is a delay in seconds to start counting the throughput
                     ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the throughput
                    ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :param format: format of unit of return value (Available 'k' - default kbits, 'm' - mbits, 'g' - gbits)
        :return: value of Average throughput in unit: Kbits/sec
        """
        omit, end = int(omit), int(end)
        if self.client_finish_time:
            delay = int(time.time() - self.client_finish_time)
        else:
            delay = 0
        self.logger.debug(f'{self.name}: counting average throughput in [{omit}:{end}] interval')
        # selecting the data source: iperf records or app's measured throughput from last n seconds
        tput_collection_src = tput_collection_src or self.dt_config['tput_collection_src']
        if tput_collection_src == CONTROL_APP_LABEL:
            self.logger.debug(f"{self.name}: counting avg throughput based on app's measured data")
            throughput_data_bps = self.ue_instance.rpc_client.get_mobile_app_average_throughput(
                ue_id=self.ue_instance.id, seconds=self.client_connected_duration,
                direction=self.dt_config['direction'])
            throughput_data_bps = throughput_data_bps[delay:]
            # recalculate period from dt_definition.duration
            set_duration = int(self._dt_definition.duration)
            if 0 < set_duration < len(throughput_data_bps):
                throughput_data_bps = throughput_data_bps[len(throughput_data_bps) - set_duration:]
        else:
            self.logger.debug(f"{self.name}: counting average throughput based on iperf output")
            interval = int(self.dt_config['interval'])
            # one iperf record per interval, so time_to_skip / interval = iperf_records_to_skip
            omit, end = self._get_omit_and_end_for_throughput(omit, end, interval)
            self.is_running()  # update dt state and output only if it is still running
            server_rows = self._get_rows_depending_on_traffic_type()
            throughput_data_bps = self.iperf_report_parser.get_normalized_bandwidth_list_without_summary(server_rows)
        if not throughput_data_bps:
            raise DataTransferException(f'{self.name}: unable to get average throughput. None of the rows received')
        if end == 0:
            data_to_count = throughput_data_bps[omit:]
        else:
            data_to_count = throughput_data_bps[omit:end]
        if not data_to_count:
            raise DataTransferException(f'{self.name,}: unable to get average throughput. Invalid omit/end is given, '
                                        'rows are empty after list slicing. '
                                        f'throughput_data_bps={throughput_data_bps}, omit={omit}, end={end}')
        self.logger.debug(f"{self.name}: counting average throughput based on normalized values to bits:"
                          f"\n{data_to_count}")
        tput_in_kbits = round(self.iperf_report_parser.get_average_from_list(data_to_count) / 1000, 2)
        self.logger.info(f'{self.name}: average throughput = {tput_in_kbits} kbits/sec')
        self._log_iperf_reports()
        self._print_avg_tput(tput_in_kbits, omit, end)
        if format and TputFormats().valid_option(format):
            factor = TputFormats().get_multiplier(format)
        else:
            factor = TputFormats().get_default_multiplier()
        return round(tput_in_kbits * factor, 2)

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        if self.datagram_loss is not None:
            return self.datagram_loss
        if self.is_running():
            raise DataTransferException(f"{self.name}: getting datagram loss of non-finished "
                                        "data transfer is not implemented.")
        if self.dt_config['protocol'] != 'udp':
            raise DataTransferException(f'{self.name}: please use UDP protocol to verify datagram loss.')
        traffic_type = self.dt_config['traffic_type']
        interval = int(self.dt_config['interval'])
        server_rows = self.iperf_report_parser.parse_and_validate_rows(
            server_lines=self.iperf_output[self.server],
            client_lines=self.iperf_output[self.client],
            iperf_interval=interval,
            traffic_type=traffic_type,
            is_parallel_streams=self._is_parallel_streams_datatransfer(),
            get_datagram_loss=True,
            burst_mode=self.burst.active)
        self.datagram_loss = self.iperf_report_parser.count_datagram_loss(server_rows)
        if self.datagram_loss is not None:
            robot_logger.info(f'{self.name}: datagram loss equals to {self.datagram_loss}%')
            return self.datagram_loss
        raise DataTransferException('None of the datagram received. Unable to count datagram loss.')

    def release_data_transfer(self):
        """Releases resources on remote UE PC."""
        self.stop(should_raise=False)
        self.logger.debug(f'{self.name}: data transfer force released. No need to release again')

    def get_data_transfer_statistics(self, omit: int = 0, end: int = 0, **kwargs):
        """
        Get data transfer statistics
        :param (int) omit: it is a delay in seconds to start counting the tput
            ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param (int) end: it is end time in seconds to stop counting the tput
            ex. '40' - it takes into account data till 40 second of transfer.
        :return: (string): statistics formatted into string like "{avg_thr},{min_thr},{max_thr};{thr_values}"
        """
        self.logger.debug(
            f"{self.name}: Get Data Transfer Statistics with parameters: omit={omit}, end={end}"
        )
        interval = int(self.dt_config['interval'])
        omit, end = int(omit), int(end)
        if (omit / interval) >= 1:
            omit = int(omit / interval)
        if (end / interval) >= 1:
            end = int(end / interval)

        statistic_to_get = kwargs.get('statistic', 'bandwidth')
        get_statistic_from_rows = self._map_statistic_to_function(statistic_to_get)

        self._read_iperf_output_and_validate_status(obligatory_check=False)
        server_rows = self._get_rows_depending_on_traffic_type()
        if not server_rows:
            raise DataTransferException(
                f"{self.name}: unable to get data transfer statistics. None of the rows received"
            )
        statistic_value_list = get_statistic_from_rows(server_rows)
        statistic_value_list_sliced = statistic_value_list[omit:end if end else None]
        if not statistic_value_list_sliced:
            self.logger.debug('No rows in passed omit-end interval window')
            raise DataTransferException(
                f"{self.name}: Unable to get average throughput. Invalid omit/end is given, "
                f"rows are empty after list slicing. throughput_data_bps={statistic_value_list}, omit={omit}, end={end}"
            )
        self.logger.debug(
            f"{self.name}: counting average throughput "
            f"based on normalized values to bits: \n{statistic_value_list_sliced}"
        )
        throughput_stats, all_values = self.iperf_report_parser.get_data_transfer_statistics(
            statistic_value_list_sliced
        )
        avg_thr, min_thr, max_thr = (round(float(value), 2) for value in throughput_stats)
        self.logger.info(
            f"{self.name} data transfer statistics for {statistic_to_get}:\n"
            f"avg: {avg_thr} [bits/s]\n"
            f"min: {min_thr} [bits/s]\n"
            f"max: {max_thr} [bits/s]"
        )
        self.logger.info(f"RAW bits/s interval values: \n{all_values}")
        return f"{avg_thr},{min_thr},{max_thr};{all_values}"

    def reset_statistics(self):
        """
        Does nothing here.
        :return:
        """
        pass

    def get_client_report_rows(self):
        """
        Returns client iperf report received after stop data transfer, or empty list.
        :return: List[IperfServerReportRow]
        """
        return self._report2rows(self.iperf_output[self.client])

    def get_server_report_rows(self):
        """
        Returns server iperf report received after stop data transfer, or empty list.
        :return: List[IperfServerReportRow]
        """
        return self._report2rows(self.iperf_output[self.server])

    # =============== Properties ===============

    @property
    def port(self):
        """Searches for free port on iperf server endpoint or uses a pre-defined value from config"""
        if not self._port:
            port_from_config = self.dt_config['robot_kwargs'].get("port")
            if port_from_config:
                if not self.server.is_port_free(port_from_config):
                    raise NoFreePortException(f"{self.name}: got port from robot keyword argument "
                                              f"`port={port_from_config}` but it is already in use.")
                self.logger.debug(f"{self.name}: setting port based on robot keyword argument: port={port_from_config}")
                self._port = port_from_config
            else:
                self._port = self.server.find_free_port()
                self.logger.debug(f"{self.name}: setting random port from 50000-60000 range: {self._port}")
        return self._port

    @property
    def kill_previous(self):
        _kill_previous = self.dt_config['robot_kwargs'].get("kill_previous")
        if isinstance(_kill_previous, bool):
            return _kill_previous
        if isinstance(_kill_previous, str):
            return _kill_previous.lower() in ("true", "yes")
        return _kill_previous

    @property
    def client_connected_duration(self):
        if not self.client_start_time:
            # Client was not yes started
            return 0.0
        # TODO
        # if not self.client_finish_time:
        #     # Client is started, data transfer is still active
        #     return time.time() - self.client_start_time
        # # Client disconnected, data transfer already finished
        # return self.client_finish_time - self.client_start_time
        # TODO: use ^^^ this code ^^^ instead of this one:
        # Delay from start time to current time
        return time.time() - self.client_start_time
        # TODO: delay should be added in place of usage, client_connected_duration should remain unchanged

    # =============== Private methods ===============

    def _map_statistic_to_function(self, statistic):
        statistic_to_function = {
            'transfer': self.iperf_report_parser.get_normalized_transfer_list_without_summary,
            'bandwidth': self.iperf_report_parser.get_normalized_bandwidth_list_without_summary,
        }
        try:
            return statistic_to_function[statistic.lower()]
        except KeyError:
            raise DataTransferException(f"Get Data Transfer Statistics only works with statistics: "
                                        f"{statistic_to_function.keys()}, passed in was: {statistic.lower()}")

    def _independently_stop_iperf_client_and_server(self):
        """Try to kill iperf server and client with guaranty of calling kill on both hosts even with error on the way"""
        self.logger.debug(f"{self.name}: stopping iperf client on {repr(self.client)}")
        result_or_error_client = self._run_action_without_raising(self.client.kill_iperf)  # trying to kill iperf client
        self.logger.debug(f"{self.name}: stopping iperf server on {repr(self.server)}")
        result_or_error_server = self._run_action_without_raising(self.server.kill_iperf)  # trying to kill iperf server
        # both client.kill_iperf and server.kill_iperf returns None, so error occurred if result not empty
        if result_or_error_server and result_or_error_client:
            # `raise exc1 from exc2` construction looks better, but robotframework<5.0 does not print it properly
            raise DataTransferStopFailedTwice(server_exc=result_or_error_server[0],
                                              server_traceback=result_or_error_server[1],
                                              client_exc=result_or_error_client[0],
                                              client_traceback=result_or_error_client[1])
        elif result_or_error_server or result_or_error_client:
            raise result_or_error_server[0] or result_or_error_client[0]  # reraise exc
        self.logger.debug(f"{self.name}: data transfer successfully stopped")
        self.is_dt_running = False

    @staticmethod
    def _run_action_without_raising(action, *args, **kwargs):
        """
        Runs action and handles an Exception if occurred
        :param action: function/method to run
        :param args: action args
        :param kwargs: action kwargs
        :return: action result if action run successfully, Exception and traceback if not;
            Be aware - in negative case return type is a tuple!!!
        """
        try:
            return action(*args, **kwargs)
        except Exception as e:
            return e, traceback.format_exc()

    def _start_iperf_and_wait_for_startup(self, endpoint, timeout=0):
        iperf_cmd = self._build_iperf_command(endpoint=endpoint, port=self.port)
        endpoint.get_app_server_iperf_version() if isinstance(endpoint, AppServerIperfEndpoint) else None
        self.logger.debug(f'{self.name}: starting iperf on {repr(endpoint)} with command: {iperf_cmd}')
        endpoint.start_iperf(cmd=iperf_cmd)
        self._wait_for_iperf_startup(endpoint=endpoint, timeout=timeout)

    def _ensure_bandwidth_is_set_for_udp(self):
        """Check if bandwidth argument is set if protocol is udp"""
        if self._dt_definition.protocol == 'udp' \
                and 'bandwidth' not in self._dt_definition.protocol_details \
                and not self._dt_definition.throughput:
            raise DataTransferIllegalArguments(f"{self.name}: Please provide bandwidth or throughput argument at the end"
                                               " of keyword if you use udp protocol, for example bandwidth=80M")

    def _set_allowed_iperf_delays(self):
        """
        Sets allowed iperf timeouts both for client and server not to answer
        Error will be raised if iperf did not respond for last n seconds
        """
        allowed_delay = int(self.dt_config['interval']) * MAX_IPERF_INTERVALS_DELAY
        server_close_delay = int(self.dt_config['server_close_delay'])
        client_close_delay = server_close_delay  # The only source the value can be changed from, is server_close_delay
        self.allowed_iperf_delay = {
            self.client: allowed_delay + client_close_delay if client_close_delay > 0 else allowed_delay,
            self.server: allowed_delay + server_close_delay if server_close_delay > 0 else allowed_delay
        }

    def _create_ssh_manager_and_register_host(self, app_server):
        """Creates an ssh manager and registers app_server to connect to remote"""
        self.logger.debug(f"{self.name}: creating ssh manager for iperf data transfer")
        ssh_manager = SshManager()
        ssh_manager.register(app_server['address'], app_server['user'], app_server['password'])
        return ssh_manager

    def _ensure_endpoint_is_alive(self, endpoint):
        """Checks if iperf did not exceed the allowed answer delay"""
        if endpoint in self.last_read_time:
            allowed_delay = self.allowed_iperf_delay[endpoint]
            self.logger.debug(f"{self.name}: checking if {repr(endpoint)} last read time did not exceeded "
                              f"allowed delay {allowed_delay}s")
            if time.time() - self.last_read_time[endpoint] > allowed_delay:
                raise IperfStuckException(
                    f"During {self.name} data transfer iperf endpoint {repr(endpoint)} was not receiving data for "
                    f"more than: {self.allowed_iperf_delay[endpoint]}s.\n"
                    "Please verify your network connectivity between client and server. When connection is fine, "
                    "please consider to change 'server_close_delay' to greater value inside configuration of "
                    "'TafUeDataTransferProtocol'")
        else:
            self.logger.debug(f"{self.name}: {repr(endpoint)} didn't start iperf yet. Skipping allowed delay check.")

    def _is_iperf_started(self, endpoint):
        """Searches iperf output for specific str which means that iperf successfully started"""
        if endpoint is self.client:
            if int(self.dt_config['version']) == 2:
                start_strs = ["Client connecting"]
            else:
                start_strs = [f"Connecting to host {self.server.get_iperf_connection_ip()}"]
        else:
            start_strs = ["Server listening", "Linux"]
        return any(start_str in line for start_str in start_strs for line in self.iperf_output[endpoint])

    def _validate_possible_iperf_problems(self, endpoint, output_lines, errors_dict):
        """Searches the output_lines for specific errors"""
        assert isinstance(errors_dict, dict)
        assert all(key in errors_dict for key in ('common', 'client', 'server'))
        common_errors = errors_dict['common']
        host_specific_errors = errors_dict['client' if endpoint is self.client else 'server']
        problems_to_check = dict(common_errors, **host_specific_errors)
        self.logger.debug(f"{self.name}: searching for the following possible errors in iperf output from "
                          f"{repr(endpoint)}:\n\t{set(problems_to_check.keys())}")
        for error_str, exc_info in problems_to_check.items():
            if any(error_str in ''.join(line) for line in output_lines):
                # TODO vbondar: workaround to automate error checking;
                #  think about more generic and structurally correct solution
                report_err_msg = exc_info['msg'].format(endpoint=endpoint, dt_name=self.name, port=self.port)
                report_footer = f"\nIPERF COMMANDS: {self.iperf_cmds}\nIPERF REPORTS: {self.iperf_output}"
                raise exc_info['class'](report_err_msg + report_footer)
        self.logger.debug(f"{self.name}: no errors found in iperf output from {repr(endpoint)}")

    def _wait_for_iperf_startup(self, endpoint, timeout=0):
        """Wait for iperf to startup"""
        # timeout from config if it is set or default allowed delay
        timeout = timeout if timeout > 0 else self.allowed_iperf_delay[endpoint]
        self.logger.debug(f"{self.name}: awaiting for iperf to start on {repr(endpoint)} for {timeout}s")
        end_time = time.time() + timeout
        while time.time() < end_time:
            self._read_iperf_output(endpoint)
            self._validate_possible_iperf_problems(endpoint, self.iperf_output[endpoint], IPERF_STARTUP_ERRORS)
            self._ensure_endpoint_is_alive(endpoint)
            if self._is_iperf_started(endpoint):
                took_time = round(timeout - end_time + time.time(), 3)
                self.logger.debug(f"{self.name}: iperf successfully started on {repr(endpoint)}, it took {took_time}s")
                if endpoint is self.server:
                    time.sleep(2)  # Server may need some more time to start before client is able to connect
                return
            time.sleep(0.5)
        raise IperfStuckException(f'During {self.name} data transfer iperf did not started on {repr(endpoint)} '
                                  f'in {timeout}s\nPlease verify your network connectivity between client and server.')

    def _read_iperf_output_and_validate_status(self, obligatory_check=True):
        self._read_iperf_output(self.server)
        self._read_iperf_output(self.client)
        if not self.client.is_iperf_running():
            self.client_finish_time = time.time()
            self.logger.debug(f"{self.name}: iperf client is not running, recording data transfer finish "
                              f"time: {self.client_finish_time}")
            if self.dt_config['direction'] == 'dl':
                lines = self.client.iperf_reader.really_read_lines()
                for line in lines:
                    self.logger.debug(f"read iperf client (ssh) AFTER CLOSE: {line}")
                self.iperf_output[self.client].extend(lines)
        if obligatory_check:
            self._ensure_endpoint_is_alive(self.server)
            self._ensure_endpoint_is_alive(self.client)

    def _read_iperf_output(self, endpoint):
        self.logger.debug(f'{self.name}: reading iperf output on {repr(endpoint)}')
        new_lines = endpoint.read_iperf_output()
        if new_lines:
            self.last_read_time[endpoint] = time.time()
            joined_lines = "\n\t".join(new_lines)
            self.logger.debug(f'{self.name}: read {len(new_lines)} lines from {repr(endpoint)}:\n{joined_lines}\n'
                              f'Last read time: {self.last_read_time[endpoint]}')
            self.iperf_output[endpoint].extend(new_lines)
            self._validate_possible_iperf_problems(endpoint, new_lines, IPERF_EXECUTION_ERRORS)
        else:
            self.logger.debug(f"{self.name}: No new lines from {repr(endpoint)}")

    def _build_iperf_command(self, endpoint, port):  # Noqa: C901
        """
        Create an iperf command based on yaml config and robot keyword arguments.
        The function caches a created command for specified endpoint in self.iperf_cmds for further method calls.
        :param endpoint: indicates for which endpoint the command is dedicated
                         possible values: self.client, self.server
        :param port: selected iperf server port
        :return: string iperf command for client or server
        """
        assert isinstance(endpoint, AbstractIperfEndpoint)
        # if command already created, return it
        if endpoint in self.iperf_cmds:
            self.logger.debug(f'{self.name}: iperf command for {repr(endpoint)} is already created:\n\t'
                              f'{self.iperf_cmds[endpoint]}')
            return self.iperf_cmds[endpoint]
        options = []
        # client specific
        if endpoint is self.client:
            options.append(f'-c {self.server.get_iperf_connection_ip()}')
            if not self.burst.active:
                options.append(f'-t {self.dt_config["duration"]}')
        # server specific
        else:
            options.append('-s')

        # common options
        if self.dt_config['protocol'] == 'udp' and \
                (endpoint is self.client or endpoint is self.server and int(self.dt_config['version']) == 2):
            options.append('-u')
        options.append(f'-p {port}')
        options.append(f'-i {self.dt_config["interval"]}')
        if endpoint.get_bind_ip() is not None:
            options.append(f'-B {endpoint.get_bind_ip()}')

        iperf_version_specific = self._load_version_specific_iperf_option(int(self.dt_config['version']),
                                                                          self.dt_config['app_server']['ip_version'])
        if iperf_version_specific != "":
            options.append(iperf_version_specific)

        # special options
        specific_iperf_options = self._load_additional_iperf_options(endpoint)
        options.extend(specific_iperf_options.values())

        # create iperf command
        if endpoint is self.client and self.burst.active:
            self.logger.debug(f"{self.name}: DT with `burst mode` activated with interval properties: "
                              f"{self.burst.cycles=}, {self.burst.cycle_sleep_duration=}")
            iperf_cmd = (f'{endpoint.get_iperf_path()} --version;c1="{endpoint.get_iperf_path()} {" ".join(options)} 2>&1";'
                         f'c2="sleep {self.burst.cycle_sleep_duration}";for i in $(seq {self.burst.cycles});'
                         'do $c1 && $c2; done')
        else:
            iperf_cmd = f'{endpoint.get_iperf_path()} --version; {endpoint.get_iperf_path()} {" ".join(options)} 2>&1'
        self.logger.debug(f'{self.name}: created iperf command for {repr(endpoint)}:\n\t{iperf_cmd}')
        self.additional_options[endpoint] = specific_iperf_options
        self.iperf_cmds[endpoint] = iperf_cmd
        return iperf_cmd

    def _load_version_specific_iperf_option(self, version, ip_version):
        additional_option = ""
        # iperf3 specific
        if version >= 3:
            additional_option = '--forceflush'
        # iperf2 specific
        else:
            if ip_version == 6:
                additional_option = '-V'
        return additional_option

    def _load_additional_iperf_options(self, endpoint, default_endpoint="client"):
        """
        Loads iperf options that are listed in iperf_options.py with _client/_server postfix from robot keyword kwargs
        iperf_options yaml section is not used anymore, robot arguments is the only source for such options
        Iperf options without endpoint role postfix are read as client arguments by default
        """
        # TODO move to config packer
        endpoint_role = "client" if endpoint is self.client else "server"  # detect endpoint role
        iperf_version = endpoint.iperf_binary if endpoint.iperf_binary in IPERF_OPTIONS.keys() else "other"
        iperf_options_by_version = IPERF_OPTIONS[iperf_version]  # iperf options depending on binary name
        common_options = iperf_options_by_version["common"]  # iperf options common for client and server
        host_specific_options = iperf_options_by_version[endpoint_role]  # iperf options for specific role
        host_specific_options.update(common_options)
        cli_options = {}
        # Searching in Start Data Transfer robot keyword arguments
        for option_name, option_value in self.dt_config["robot_kwargs"].items():
            if option_value is None:
                self.logger.debug(f"Skipping empty robot keyword argument: {option_name}={option_value}")
                continue
            option_name_without_postfix = "_".join(option_name.split("_")[:-1])
            option_postfix = option_name.split("_")[-1]
            if option_name in host_specific_options:
                cli_argument = host_specific_options[option_name]
            elif option_postfix == endpoint_role and option_name_without_postfix in common_options:
                # Loading iperf option set with endpoint role postfix
                cli_argument = common_options[option_name_without_postfix]
            else:
                # Keyword argument in robot kwargs is not dedicated for this method or unsupported, skipping
                continue
            cli_argument_repr = self._get_iperf_option_string_by_value_type(cli_argument, option_value)
            if cli_argument_repr:
                cli_options[cli_argument] = cli_argument_repr
                self.logger.debug(f"Setting iperf cli option for {endpoint} based on {option_name} "
                                  f"robot keyword argument: {cli_argument_repr}")
            else:
                self.logger.debug(f"Skipping {cli_argument} iperf cli option for {endpoint} based on "
                                  f"{option_name}={option_value} robot keyword argument")
        return cli_options

    @staticmethod
    def _get_iperf_option_string_by_value_type(cli_argument, argument_value):
        """
        Return string representation of iperf cli argument depending on its type
        E.g. "-v" if flag is boolean, "-v value" if flag requires a value
        :param cli_argument: iperf argument name
        :param argument_value:  iperf argument value
        :return: flag name if value is true
                 None if value is false
                 flag name with value if value is not boolean
        """
        try:
            is_arg_flag = argument_value.strip().lower() in ('y', 'yes', 't', 'true')
            if argument_value is True or is_arg_flag is True:
                return cli_argument
            raise ValueError
        except ValueError:
            return f"{cli_argument} {argument_value}"

    def _log_iperf_reports(self, tail=0):
        client_lines_report = self.iperf_output[self.client][-tail:]
        server_lines_report = self.iperf_output[self.server][-tail:]
        iperf_cmds_report = '\n'.join(f"{k} = {v}" for k, v in self.iperf_cmds.items())
        robot_logger.info(f"iperf cmds: {iperf_cmds_report}")
        self.reports_received = True
        try:
            robot_logger.info('\nDt {} iperf client report:\n{}'.format(self.name, '\n'.join(client_lines_report)))
            robot_logger.info('\nDt {} iperf server report:\n{}'.format(self.name, '\n'.join(server_lines_report)))
        except UnicodeEncodeError as e:
            self.logger.debug(f"UnicodeEncodeError: {client_lines_report} \n {server_lines_report}")
            self.logger.error(e, exc_info=True)
            raise e

    @staticmethod
    def _print_avg_tput(avg, omit, end, line_length=54):
        robot_logger.info("-" * line_length)
        robot_logger.info("Average throughput was calculated by the plugin \n"
                          f"in the range [{omit}, {end}] and equals {avg} KBits/sec")
        robot_logger.info("-" * line_length)

    def _get_rows_depending_on_traffic_type(self):
        return self.iperf_report_parser.parse_to_rows(self.iperf_output[self.server],
                                                      self._is_parallel_streams_datatransfer(),
                                                      include_nans=self.dt_config['traffic_type'] != 'nbiot',
                                                      burst_mode=self.burst.active)

    def _is_parallel_streams_datatransfer(self):
        if PARALLEL_STREAMS in self.additional_options[self.client]:
            parallel_streams_value = int(self.additional_options[self.client][PARALLEL_STREAMS].split()[1])
            if parallel_streams_value > 1:
                return True
        return False

    def _get_omit_and_end_for_throughput(self, omit, end, interval):
        if (omit / interval) >= 1:
            omit = int(omit / interval)
        if (end / interval) >= 1:
            end = int(end / interval)
        return omit, end

    @staticmethod
    def _report2rows(report):
        rows = []
        for line in report:
            row = IperfServerReportRow(line)
            if row.correct:
                rows.append(row)
        return rows


class AndroidUeDtConfigPacker:
    """AndroidUeDtConfigPacker"""

    def __init__(self, dt_definition, yaml_config, logger):
        """
        Packs data transfer settings from DataTransferDefinition (robot kwargs) and
        yaml config (configuration & data_transfer section) into one dict
        :param dt_definition: DataTransferDefinition class instance
        :param yaml_config: data_transfer section from yaml config
        """
        # TODO refactor
        self.dt_logger = logger
        self.dt_definition = dt_definition
        self.dt_config_to_uepc = {'app_server': self.get_app_server(yaml_config,
                                                                    dt_definition.protocol_details),
                                  'direction': dt_definition.direction,
                                  'duration': self._get_data_transfer_duration(dt_definition, logger),
                                  'protocol': dt_definition.protocol,
                                  'robot_kwargs': dt_definition.protocol_details}
        self.set_ip_version_for_app_server()
        self._pack_dt_keys(yaml_config)

        if dt_definition.protocol == 'udp' or dt_definition.protocol == 'tcp' and not dt_definition.has_default_tput():
            self._map_legacy_throughput_to_bandwidth(dt_definition)

    @staticmethod
    def _get_data_transfer_duration(dt_definition, logger):
        if dt_definition.is_forever_duration() or dt_definition.duration > DT_MAX_TIME:
            logger.warning(f"Data transfer duration in {dt_definition} is too long (duration={dt_definition.duration}). "
                           f"Setting default duration value due to software limitations: {DT_MAX_TIME}s")
            return DT_MAX_TIME
        else:
            return dt_definition.duration

    def _pack_dt_keys(self, configuration):
        dt_allowed_keys = {'binary_path': None,
                           'bind_ue_ip': True,
                           'interface_name': None,
                           'interval': 1,
                           'packet_server': None,
                           'packet_size_server': None,
                           'packet_size': None,
                           'port': 0,
                           'server_close_delay': 0,
                           'tput_collection_src': 'iperf',
                           'traffic_type': None,
                           'version': 2,
                           'iperf_version': 2,
                           'kill_previous': False}
        dt_section = configuration['data_transfer']['iperf']

        self._apply_allowed_keys(dt_section, dt_allowed_keys)

    def _apply_allowed_keys(self, yaml_config_section, allowed_keys):
        """
        Applies allowed keys from selected section into dt dict that goes to UE PC
        :param yaml_config_section: a section of yaml config that responds for configuration of data transfers
        :param allowed_keys: a dict o keys to search in current yaml config section and a default values for them
        :return:
        """
        for key, default_value in allowed_keys.items():
            if key in self.dt_definition.protocol_details and self.dt_definition.protocol_details[key] is not None:
                self.dt_config_to_uepc[key] = self.dt_definition.protocol_details[key]
            elif key in yaml_config_section and yaml_config_section[key] is not None:
                self.dt_config_to_uepc[key] = yaml_config_section[key]
            else:
                self.dt_config_to_uepc[key] = default_value
        if self.dt_config_to_uepc['iperf_version'] is not allowed_keys['iperf_version']:
            self.dt_config_to_uepc['version'] = self.dt_config_to_uepc['iperf_version']

    def _apply_key(self, config_section, key, preferred_type=None, default_value=None):
        """
        Applies allowed key from selected section into dt dict that goes to UE PC
        :param config_section: a section of yaml config that responds for configuration of data transfers
        :param key: an option to search in current yaml config section
        :param preferred_type: if key value is found it will be converted to preferred_type if it is set
        :param default_value: default key value if no such key in yaml config section
        :return:
        """
        searched_option = self.dt_definition.protocol_details.get(key, config_section.get(key, default_value))
        if preferred_type and isinstance(preferred_type, type) and searched_option is not None:
            searched_option = preferred_type(searched_option)
        self.dt_config_to_uepc[key] = searched_option

    def get_app_server(self, yaml_config, robot_kwargs):
        """Load app server details from yaml config """
        if 'app_server' in robot_kwargs:
            whole_config = Config().get_config()
            app_server = None
            if whole_config and robot_kwargs['app_server'] in whole_config:
                app_server = whole_config[robot_kwargs['app_server']]

            if not app_server:
                raise DataTransferNotAvailableException("Please verify you app server list at configuration yaml:\n"
                                                        f"The \'{robot_kwargs['app_server']}\' app server is missing.\n"
                                                        f"App servers configured: {yaml_config.keys()}\n")
            return app_server
        try:
            return self._get_app_server_from_yml(yaml_config)
        except KeyError:
            raise KeyError(f"Yaml config missing app_server configuration on {yaml_config.get('serial_number')} UE \n"
                           "and app_server robot keyword was not specified in Start Data Transfer. \n"
                           "Please, update your yaml config and try again.")

    @staticmethod
    def _get_app_server_from_yml(yaml_config):
        return yaml_config['data_transfer']['iperf']['app_server']

    def set_ip_version_for_app_server(self):
        """Set ip version for app server based on iperf_interface_ip"""
        app_server = self.dt_config_to_uepc['app_server']
        if 'bind_interface_ip' in app_server and app_server['bind_interface_ip']:
            ip_version = get_ip_version(app_server['bind_interface_ip'])
        else:
            try:
                ip_version = get_ip_version(app_server['address'])
            except KeyError:
                ip_version = None
        self.dt_config_to_uepc['app_server']['ip_version'] = ip_version

    @staticmethod
    def has_multiple_app_servers_defined_in_config(app_servers_section):
        """Method's name says everything"""
        return len(app_servers_section) > 1

    def get_config(self):
        """Methods name says everything"""
        return self.dt_config_to_uepc

    @staticmethod
    def _map_legacy_throughput_to_bandwidth(dt_definition):
        """Maps legacy throughput parameter into bandwidth before inserting into packed UE PC config"""
        if not dt_definition.protocol_details.get('bandwidth', ''):
            dt_definition.protocol_details['bandwidth'] = f'{int(dt_definition.throughput)}{UNIT_OF_DT_DEFINITION_THROUGHPUT}'
        return dt_definition
